 if(S.step>=STEPS.length){$('#lxStageHeading').textContent='Walkthrough complete';$('#lxStageSub').textContent='All 10 local HITL acknowledgments recorded in this browser.';$('#lxStageBadge').textContent='SIMULATION COMPLETE';$('#lxStepBody').innerHTML='<div class="lx-data"><h3>Simulation only</h3><div class="lx-datarow"><span class="lx-dot">✓</span>Ten staged human acknowledgments and an exportable unsigned event trail.</div><div class="lx-warning">No actual order, manufacturing, shipping, financial transfer, or independent authorization occurred.</div></div>';$('#lxHuman').innerHTML='<div class="lx-human-head"><b>Local preview completed</b><span>EXTERNAL EFFECTS 0</span></div><button class="lx-primary" data-act="export">Export review & event evidence</button> <button class="lx-secondary" data-act="sample" data-sample="bracket">Restart sample</button>';return;}
 const s=STEPS[step],g=gate(),wrongRole=S.role!==s.role;
