 $('#lxStepBody').innerHTML=evidenceRows(step)+`${S.changeHold&&isDemo()&&!S.rejected?'<div class="lx-actions" style="margin-top:10px"><button class="lx-secondary" data-act="resolveChange">Revise demo assumptions & re-review</button></div>':''}${S.step===4&&isDemo()&&!S.requote?'<div class="lx-actions" style="margin-top:11px"><button class="lx-secondary" data-act="requote">Request revised synthetic quote ($495)</button></div>':''}${S.step===8&&isDemo()?'<div class="lx-actions" style="margin-top:11px"><button class="lx-secondary" data-act="qualityhold">Introduce quality hold</button><button class="lx-secondary" data-act="qualityresolve">Resolve simulated hold</button></div>':''}${S.source.kind==='rebot'&&S.step===1?'<div class="lx-actions" style="margin-top:10px"><button class="lx-secondary" data-act="observe">Run read-only source observation (GET)</button></div>':''}`;
 $('#lxHuman').innerHTML=`<div class="lx-human-head"><b>Human review required — ${esc(s.owner)}</b><span>${esc(wrongRole?'WRONG ROLE':g.ready?'SIMULATED GATE':'NO-GO / Z')}</span></div><div class="lx-human-row"><label>Named human reviewer (not authenticated)<input id="lxReviewer" autocomplete="off" maxlength="60" placeholder="Type your name" value="${esc(S.names[S.role])}"></label><label>Responsible workspace<select id="lxReviewRole">${Object.keys(labelrole).map(k=>`<option value="${k}" ${S.role===k?'selected':''}>${labelrole[k]}</option>`).join('')}</select></label></div><label class="lx-checklabel"><input type="checkbox" id="lxAttest" ${S.ack?'checked':''}><span>I reviewed this stage and understand that acknowledgment is ${isDemo()?'simulation only':'not engineering admission'}.</span></label><div class="lx-actions"><button class="lx-primary" id="lxAdvance" data-act="approve" ${canAdvance()?'':'disabled'}>Confirm stage & continue →</button><button class="lx-secondary" data-act="change">Request changes</button><button class="lx-danger" data-act="reject">Reject / hold</button>${wrongRole?`<button class="lx-secondary" data-act="switchRequired">Switch to ${esc(labelrole[s.role])}</button>`:''}</div><div class="lx-action-note">${!g.ready?'STOP: '+esc(g.why):wrongRole?'This stage requires '+esc(s.owner)+' review.': 'Only an explicitly named human can progress this demo. No external effects.'}</div>`;
